<script setup lang="ts">
import {ref} from 'vue';import {onLoad} from '@dcloudio/uni-app';import PageShell from '../../components/PageShell.vue';import {usePage} from '../../composables/usePage';import {request} from '../../utils/request';import {go,money,time,status,confirm} from '../../utils/format'
const id=ref(0),order=ref<any>(null);onLoad(q=>id.value=Number(q?.id));const {loading,error,load,busy,action}=usePage(async()=>order.value=await request('/orders/'+id.value));async function cancel(){if(await confirm('确认取消尚未匹配喂养师的订单？')){await request('/orders/'+id.value+'/cancel','POST',{reason:'宠主主动取消'});await load()}}
const events:Record<string,string>={CREATED:'预约已提交',PAID:'支付已确认',ASSIGNED:'平台已派单',ACCEPTED:'喂养师已接单',REJECTED:'喂养师拒单，重新调度',CHECKIN:'进门打卡',COMPLETED:'服务完成，已离门',REVIEWED:'评价已提交',CANCELLED:'订单已取消',REFUNDED:'退款已完成'}
</script><template><PageShell title="订单详情" back :loading="loading" :error="error" @retry="load"><template v-if="order"><view class="pill">{{status(order.status)}}</view><view class="title" style="margin:14px 0 8px">{{order.status==='COMPLETED'?'今天的照顾，圆满完成。':'每一步，都让你安心。'}}</view><view class="muted" style="margin-bottom:24px">{{order.order_no}}</view><view v-if="order.status==='DISPATCHING'" class="notice">平台正在结合订单备注和喂养师经验自动匹配，暂不需要付款。</view><view class="card"><view style="font-weight:700">{{order.pet_snapshot?.map((p:any)=>p.name).join('、')}}</view><text class="muted">{{time(order.service_start)}} – {{String(order.service_end).slice(11,16)}}</text><view class="divider"/><view>{{order.address_snapshot?.district}} · {{order.address_snapshot?.address}}</view><text class="muted">{{order.notes||'无额外照护要求'}}</text><view class="divider"/><view v-for="i in order.items" :key="i.id" class="row"><text>{{i.name}} × {{i.quantity}}</text><text>{{money(i.unit_price*i.quantity)}}</text></view><view class="divider"/><view class="row"><text>实际应付</text><text class="amount">{{money(order.payable_amount)}}</text></view></view><view v-if="order.sitter" class="card"><view class="row-start"><view class="avatar">☺</view><view><view>{{order.sitter.name}} · {{order.sitter.grade_code}}</view><text class="muted">评分 {{order.sitter.rating}} · 完单 {{order.sitter.completed_orders}}</text></view></view><view v-if="order.dispatch?.reason" class="notice" style="margin:14px 0 0">派单说明：{{order.dispatch.reason}}</view></view><view class="section">服务时间轴 <text class="link" @click="load">刷新</text></view><view class="card"><view class="timeline"><view v-for="e in order.timeline" :key="e.id" class="timeline-item"><view>{{events[e.event]||e.event}}</view><text class="muted">{{time(e.created_at)}}</text></view></view></view><view class="stack"><button v-if="order.status==='PENDING_PAYMENT'" class="outline full-width" @click="action(cancel,'')">取消订单</button><button v-if="order.status==='SERVICING'" class="primary" @click="go('owner/servicing?id='+id)">查看服务直播报</button><button v-if="order.status==='COMPLETED'" class="primary" @click="go('owner/report?id='+id)">查看喂养记录与报告</button><button v-if="order.status==='COMPLETED'&&!order.review" class="secondary" @click="go('owner/review?id='+id)">评价这次服务</button><view v-if="order.review" class="card">已评价 {{order.review.score}} 星 · {{order.review.content}}</view><button class="outline full-width" @click="go('owner/service?orderId='+id)">联系服务群 / 客服</button></view></template></PageShell></template>

